use super::*;

/// The receivables ledger. Outstanding first, because that is the money not yet in the account.
///
/// The AMBIGUOUS section is deliberately above the matched one. A matched credit needs no attention;
/// a credit that fits two invoices needs a decision, and burying it under a list of settled rows is
/// how it stops being made.
pub fn render_invoices(
    settlements: &[invoice::Settlement],
    buckets: &[invoice::AgeBucket],
    m: &invoice::MatchResult,
    priced: &[invoice::Priced],
    as_of: &str,
) -> String {
    let mut out = String::new();
    let fm = crate::money::format_minor;
    out.push_str(&format!("Receivables as of {as_of}\n\n"));

    let owed: i64 = settlements.iter().filter(|s| s.state.is_outstanding()).map(|s| s.outstanding.minor).sum();
    if settlements.is_empty() {
        out.push_str("  No invoice has been issued yet.\n");
        out.push_str("  Raise one:  bsc fin invoice new INV-001 \"Client Name\" 2400.00 --due 2026-07-01\n");
        return out;
    }
    out.push_str(&format!("  Outstanding  {:>12}\n", fm(owed)));
    let received: i64 = m.matched.iter().map(|p| p.amount.minor).sum();
    out.push_str(&format!("  Received     {:>12}   across {} matched credit(s)\n\n", fm(received), m.matched.len()));

    if !m.ambiguous.is_empty() {
        out.push_str("  NEEDS A DECISION — these credits fit more than one invoice equally:\n");
        for a in &m.ambiguous {
            out.push_str(&format!("    {}  {:>12}  {}\n", a.date, fm(a.amount.minor), clip(&a.description, 34)));
            out.push_str(&format!("      could be: {}\n", a.candidates.join(" or ")));
        }
        out.push('\n');
    }

    let live: Vec<&invoice::Settlement> = settlements.iter().filter(|s| s.state.is_outstanding()).collect();
    if !live.is_empty() {
        out.push_str("  Owed\n");
        for s in &live {
            out.push_str(&format!(
                "    {:<14} {:<20} {:>12}  {}\n",
                clip(&s.invoice, 13),
                clip(&s.client, 19),
                fm(s.outstanding.minor),
                s.state.label()
            ));
        }
        out.push('\n');
    }

    let aged: Vec<&invoice::AgeBucket> = buckets.iter().filter(|b| !b.invoices.is_empty()).collect();
    if !aged.is_empty() {
        out.push_str("  Ageing\n");
        for b in aged {
            out.push_str(&format!("    {:<10} {:>12}   {}\n", b.label, fm(b.total.minor), b.invoices.join(", ")));
        }
        out.push('\n');
    }

    // TAX IS SHOWN ONLY WHERE IT IS NOT A SETTLED ZERO. A line per exempt invoice would bury the
    // two rows that need an action under a column of "exempt", which is the shape that stops a
    // report being read.
    let notable: Vec<&invoice::Priced> = priced.iter().filter(|p| !matches!(p.tax, invoice::TaxOutcome::None { .. })).collect();
    let exempt = priced.len() - notable.len();
    if !priced.is_empty() {
        out.push_str("  Tax\n");
        for p in &notable {
            match &p.tax {
                invoice::TaxOutcome::Charged { bps, amount, .. } => {
                    out.push_str(&format!("    {:<14} {:>12}  at {}\n", clip(&p.invoice, 13), fm(amount.minor), format_bps(*bps)));
                }
                invoice::TaxOutcome::Undetermined { what, where_to } => {
                    out.push_str(&format!("    {:<14} {:>12}  {}\n", clip(&p.invoice, 13), "UNDETERMINED", what));
                    out.push_str(&format!("      {where_to}\n"));
                }
                invoice::TaxOutcome::None { .. } => {}
            }
        }
        if exempt > 0 {
            let reason = priced
                .iter()
                .find_map(|p| match &p.tax {
                    invoice::TaxOutcome::None { reason, .. } => Some(reason.clone()),
                    _ => None,
                })
                .unwrap_or_default();
            out.push_str(&format!("    {exempt} invoice(s) carry none — {reason}\n"));
        }
        out.push('\n');
    }

    if !m.unexplained.is_empty() {
        out.push_str("  Arrived, belongs to no invoice\n");
        for t in &m.unexplained {
            out.push_str(&format!("    {}  {:>12}  {}\n", t.date, fm(t.amount.minor), clip(&t.description, 34)));
        }
        out.push('\n');
    }

    for n in &m.notes {
        out.push_str(&format!("  · {n}\n"));
    }
    out
}
